// WeaponData.cs
[CreateAssetMenu(fileName = "NewWeapon", menuName = "Game Data/Weapon")]
public class WeaponData : ScriptableObject
{
    public string weaponName;
    public int damage;
    public float attackSpeed;
    public float range;
    public Sprite icon;       // ← referencia a un asset de Unity
    public AudioClip hitSound; // ← referencia a un AudioClip
}

// WeaponController.cs — usa el ScriptableObject
public class WeaponController : MonoBehaviour
{
    [SerializeField] private WeaponData weaponData; // se asigna en el Inspector

    void Attack()
    {
        DealDamage(weaponData.damage);
        AudioSource.PlayClipAtPoint(weaponData.hitSound, transform.position);
    }
}

// Múltiples MonoBehaviours pueden referenciar el MISMO ScriptableObject
// Si cambias weaponData.damage, todos los que lo usen verán el cambio

// PlayerStats.cs — ScriptableObject para datos del jugador
[CreateAssetMenu(fileName = "PlayerStats", menuName = "Game Data/Player Stats")]
public class PlayerStats : ScriptableObject
{
    public int maxHp;
    public int currentHp;
    public int level;
    public int experience;
}

// HealthBar.cs (en escena de combate)
public class HealthBar : MonoBehaviour
{
    [SerializeField] private PlayerStats stats; // mismo asset
    void Update() => slider.value = (float)stats.currentHp / stats.maxHp;
}

// SaveSystem.cs (en escena de menú)
public class SaveSystem : MonoBehaviour
{
    [SerializeField] private PlayerStats stats; // mismo asset
    void Save() => PlayerPrefs.SetInt("HP", stats.currentHp);
}

// Al ser el mismo .asset, ambos scripts leen/escriben los mismos datos
// sin necesitar un Singleton ni DontDestroyOnLoad

