//
// Opción A: ScriptableObjects
// Opción B: JSON descargado desde servidor

[CreateAssetMenu(fileName = "NewBoss", menuName = "Enemies/Boss")]
public class BossData : ScriptableObject
{
    public string bossName;
    public int hp;
    public float speed;
    public Sprite portrait;
    public GameObject phaseTransitionVFX;
    public BossPhaseData[] phases;
}

[CreateAssetMenu(menuName = "Game/Weapon")]
public class WeaponData : ScriptableObject
{
    public int damage = 30;
}

// En runtime:
// weaponA.data y weaponB.data referencian el MISMO .asset
weaponA.data.damage = 99; // modifica el asset
Debug.Log(weaponB.data.damage); // ¿qué imprime?

